  "{@0} Správna možnosť: <strong>{@1}</strong>.": "{@0} Bonne réponse : <strong>{@1}</strong>.",
  "{@0} o ${@1}\\,\\%$ znamená, že nová cena je ${@2}\\,\\%$ pôvodnej.": "{@0} de ${@1}\\,\\%$ signifie que le nouveau prix représente ${@2}\\,\\%$ du prix initial.",
